void* handle;
typedef int (*MathFunc)(int, int);
MathFunc func_ptr;

// Load the shared library
handle = dlopen("libutil.so", RTLD_LAZY);
if (!handle) {
    // Check dlerror() for failure details
    return;
}

// Get the address of the function 'calculate'
func_ptr = (MathFunc)dlsym(handle, "calculate");

if (!func_ptr) {
    dlclose(handle);
    return;
}

// Execute the dynamically loaded function
int result = func_ptr(10, 20);

// Unload the library when finished
dlclose(handle);
